// Wallapop - verificar si el anuncio sigue en pie.
//
// Mismo endpoint que el enriquecedor, pero aqui solo interesan dos cosas: si
// existe y si esta disponible. Un 404 es una respuesta limpia y barata -unos
// 60 ms-, sin HTML que interpretar ni heuristicas de redireccion a la home.

const out = $input.item.json;
const oferta = $('Loop: oferta por oferta').item.json;
const id = oferta.id;
// Como consta ahora. Sirve para distinguir un cambio de estado de una simple
// reconfirmacion, y no mover updated_at cuando no ha pasado nada.
const eraActiva = oferta.is_active !== false;

const status = Number(out.statusCode || 0);
const cuerpo = String(out.body || '');

function esc(v) { if (v === null || v === undefined || v === '') return null; return "'" + String(v).replace(/'/g, "''") + "'"; }

// No basta con que el status sea 200: la respuesta tiene que traer DENTRO el
// anuncio que hemos pedido.
//
// Sin esta comprobacion, cualquier 200 que no fuera el anuncio -un
// interstitial, un balanceador contestando por su cuenta, una pagina de
// mantenimiento- reactivaria de golpe todas las ofertas dadas de baja, porque
// la rama de abajo pone is_active=TRUE. Es el espejo de lo que hace Imperva en
// Milanuncios, donde la pantalla de bloqueo llega tambien con un HTTP 200.
//
// Comprobado contra la API el 2026-09-06: una oferta viva devuelve 200 con un
// JSON cuyo `id` de primer nivel es el que se ha pedido; una retirada devuelve
// 404 con el cuerpo vacio.
function leeFicha(texto, idPortal) {
  if (!texto) return null;
  try {
    const j = JSON.parse(texto);
    if (!j || String(j.id) !== String(idPortal)) return null;
    return j;
  } catch (e) { return null; }
}

// Vendida o retirada. Es el unico veredicto que da de baja por no existir.
//
// Si ya constaba inactiva no se toca updated_at: se limita a rotar la fecha de
// comprobacion. Antes se reescribia cada dia, y eso borraba el unico rastro que
// queda de CUANDO se cayo el anuncio -no hay columna para esa fecha- porque lo
// dejaba pareciendo que se habia caido hoy.
if (status === 404 || status === 410) {
  const sets = eraActiva
    ? 'is_active=FALSE, last_checked_at=NOW(), updated_at=NOW()'
    : 'last_checked_at=NOW()';
  return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET ' + sets + ' WHERE id=' + esc(id), count: 1, veredicto: 'vendida' } }];
}

if (status === 200) {
  const idPortal = String(id).replace(/^wp_/, '');
  const ficha = leeFicha(cuerpo, idPortal);

  // Un 200 que no trae el anuncio no dice nada. Se rota la fecha para que la
  // cola siga girando, pero no se toca is_active ni last_seen_at: no lo hemos
  // visto.
  if (!ficha) {
    return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET last_checked_at=NOW() WHERE id=' + esc(id), count: 1, veredicto: 'respuesta rara' } }];
  }

  // Sigue publicada. Ahora bien, publicada no es lo mismo que disponible: la
  // ficha trae `reserved.flag`, igual que el buscador.
  //
  // Esto corrige una incoherencia que llevaba tiempo: el scraper SI mira
  // reserved al dar de alta la oferta, pero el verificador no, asi que una que
  // se reservaba despues de raspada se quedaba como activa para siempre. En una
  // muestra de 40 activas, el 3% estaba reservado.
  const reservada = !!(ficha.reserved && ficha.reserved.flag);
  const deberiaEstar = !reservada;

  // Se toca last_seen_at siempre que la hayamos visto, este reservada o no, y
  // no es un detalle: es lo que convierte esa columna en la fecha de baja. El
  // scraper solo lee las 40 paginas de mas recientes, asi que no vuelve a ver
  // casi ninguna oferta y last_seen_at se quedaba diciendo cuando nos la
  // cruzamos, no cuando dejo de estar publicada -en Wallapop las activas y las
  // inactivas tenian el mismo rango de fechas, indistinguibles-. Refrescandola
  // aqui pasa a significar 'la ultima vez que comprobamos que seguia en pie', y
  // en una oferta caida se congela sola en su ultimo dia bueno. Como se pasa
  // doce veces al dia, la fecha de baja sale con unas dos horas de margen. No
  // hace falta columna nueva.
  //
  // updated_at solo se mueve si el estado cambia de verdad: una oferta que
  // lleva meses disponible no tiene por que parecer tocada cada dia.
  const sets = (deberiaEstar !== eraActiva)
    ? 'is_active=' + (deberiaEstar ? 'TRUE' : 'FALSE') + ', last_checked_at=NOW(), last_seen_at=NOW(), updated_at=NOW()'
    : 'last_checked_at=NOW(), last_seen_at=NOW()';

  return [{ json: {
    sql: 'UPDATE moveadvisor_market_offers SET ' + sets + ' WHERE id=' + esc(id),
    count: 1,
    veredicto: reservada ? 'reservada' : 'viva',
  } }];
}

// 429, 5xx, timeout: no sabemos nada, asi que no se toca is_active. Solo se
// mueve last_checked_at para que la cola siga girando y no se atasque en esta
// oferta -es lo mismo que hace scripts/verify-liveness.js con las transitorias.
return [{ json: { sql: 'UPDATE moveadvisor_market_offers SET last_checked_at=NOW() WHERE id=' + esc(id), count: 1, veredicto: 'transitoria' } }];
